from pathlib import Path
from PIL import Image,ImageDraw,ImageFont
import io,base64,json,hashlib,html
r=Path(__file__).parent
names=['01_absence','02_impossible','03_distance','04_past','05_last_light','06_darkness','07_gravity','08_departure','09_payoff']
labels=['1 / The absent source','2 / Impossible premise, real delay','3 / The distance to cross','4 / Arriving from the past','5 / The last-light boundary','6 / Daylight finally ends','7 / Gravity shares the delay','8 / Tangent departure','9 / Resolving the opening']
font=ImageFont.truetype(str(r.parent/'assets/Manrope800.ttf'),18)
def sheet(ns,ls,file):
 rows=(len(ns)+2)//3;im=Image.new('RGB',(1020,rows*650+15),'#e9e4da');d=ImageDraw.Draw(im)
 for i,(n,l) in enumerate(zip(ns,ls)):
  x=15+(i%3)*335;y=43+(i//3)*650
  p=Image.open(r/'rendered'/f'{n}.jpg');p.thumbnail((320,570));im.paste(p,(x,y));d.text((x,y-30),l,fill='#0d1c2b',font=font)
 im.save(r/file,quality=94)
sheet(names,labels,'CONTACT_SHEET.jpg');sheet(['passage_0','passage_1','passage_2'],['Initial / source present','Intermediate / source removed','Resolved / final light arrives'],'HARDEST_PASSAGE.jpg')
def uri(p):
 im=Image.open(p);im.thumbnail((540,960));b=io.BytesIO();im.save(b,format='JPEG',quality=82);return 'data:image/jpeg;base64,'+base64.b64encode(b.getvalue()).decode()
def card(n,l):return '<figure><figcaption>'+html.escape(l)+'</figcaption><img class="normal" src="'+uri(r/'rendered'/f'{n}.jpg')+'"><img class="bare" src="'+uri(r/'rendered'/f'{n}_no_heading.jpg')+'"></figure>'
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Curio Bureau — Sun disappeared — Art review</title><style>*{box-sizing:border-box}body{background:#e9e4da;color:#0d1c2b;margin:0;font:16px/1.5 system-ui}header,section{max-width:1260px;margin:auto;padding:26px}h1{font:700 38px/1.1 Georgia;max-width:780px}p{max-width:880px}.eyebrow{letter-spacing:.15em;font-size:12px;font-weight:800}button{border:0;padding:14px 22px;background:#0d1c2b;color:#f5f0e7;font-weight:700;cursor:pointer}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:22px}figure{margin:0}figcaption{min-height:55px;font-weight:700}img{width:100%;display:block}.bare{display:none}.nohead .normal{display:none}.nohead .bare{display:block}.note{border-top:1px solid #aeb4b3;padding-top:16px}audio{width:min(650px,100%)}@media(max-width:720px){.grid{grid-template-columns:1fr}h1{font-size:30px}}</style><header><div class="eyebrow">CURIO BUREAU / EXPERIMENT 01 / STATIC ART REVIEW</div><h1>If the Sun disappeared, when would you notice?</h1><p>Complete nine-beat visual sequence and three connected states of the hardest transit passage. These are finished static artwork states, not an animated preview. Camera/object choreography is planned for 12 distinct states per second, with meaningful operations every 1.5–2 seconds in a native 1080p30 film.</p><p>The Sun cannot actually vanish. Earth and Sun sizes, travel markers and orbital geometry are simplified and not to scale. The city is an AI photographic illustration, the Earth is a NASA MODIS composite, and the Sun is an assigned-color NASA/SDO image. No halos, blurred backdrops or added shadows.</p><button onclick="document.body.classList.toggle('nohead')">Show / hide decorative headlines</button></header><section><h2>The whole story</h2><div class="grid">'''+''.join(card(n,l) for n,l in zip(names,labels))+'''</div></section><section><h2>Hardest passage: remove the source, preserve the light in transit</h2><p>The absence boundary travels from the Sun toward Earth. The light ahead of it continues to Earth. The same Earth anchor remains fixed in all three views; the drawing is conceptual.</p><div class="grid">'''+''.join(card('passage_'+str(i),l)for i,l in enumerate(['Before removal','Halfway across','Last sunlight reaches Earth']))+'''</div></section><section><h2>Recorded narration</h2><p>47.59 seconds of decoded narration after removing 0.65 seconds from a measured silent interval. Speech samples and speed are preserved. This is narration only; music and SFX are not yet mixed.</p><audio controls src="data:audio/mpeg;base64,NARRATION_AUDIO"></audio><p class="note">Approval applies to artwork and visual sequence. Full animation, 12fps cadence, actual 1.5–2-second timing, soundtrack, captions and the exact established ending remain separate moving-video checks.</p><p><a href="https://spaceplace.nasa.gov/all-about-the-sun/en/">NASA: sunlight travel time</a> · <a href="https://gracefo.jpl.nasa.gov/news/5/what-is-gravity/">NASA/JPL: the hypothetical gravitational delay</a></p></section></html>'''
mp3=r.parent/'audio/voice-review.mp3'
page=page.replace('NARRATION_AUDIO',base64.b64encode(mp3.read_bytes()).decode())
(r/'REVIEW.html').write_text(page)
print('Built self-contained review, whole-story sheet and three-state passage.')
